/* Original implementation of the reference's playable-headline interaction. */
(() => {
  const board=document.querySelector('#game-board'),canvas=document.querySelector('#game-canvas'),button=document.querySelector('#game-start'),status=document.querySelector('#game-status'),livesEl=document.querySelector('#game-lives');
  const ctx=canvas.getContext('2d');if(!ctx)return;
  const reduce=matchMedia('(prefers-reduced-motion: reduce)');
  const glyphs={H:['10001','10001','10001','11111','10001','10001','10001'],E:['11111','10000','10000','11110','10000','10000','11111'],L:['10000','10000','10000','10000','10000','10000','11111'],O:['01110','10001','10001','10001','10001','10001','01110'],W:['10001','10001','10001','10101','10101','10101','01010'],R:['11110','10001','10001','11110','10100','10010','10001'],D:['11110','10001','10001','10001','10001','10001','11110']};
  let w=0,h=0,cell=0,bricks=[],ball={},paddle={},phase='attract',lives=3,raf=0,last=0,visible=false,clock=0;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function hud(){livesEl.replaceChildren();if(phase==='playing')for(let i=0;i<lives;i++)livesEl.append(document.createElement('span'));button.hidden=phase==='playing';button.textContent=phase==='over'||phase==='won'?'Again':'Play';status.textContent=phase==='playing'?'Playing':phase==='over'?'Out of balls':phase==='won'?'Cleared':'Ready';board.dataset.phase=phase;board.style.touchAction=phase==='playing'?'none':'pan-y';}
  function serve(){ball={x:w/2,y:h*.75,r:clamp(cell*.4,4,8),vx:w*.17,vy:-h*.5};}
  function reset(){w=board.clientWidth;h=board.clientHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);cell=Math.min(w*.9/29,h*.58/16);const left=(w-cell*29)/2,top=h*.16;bricks=[];['HELLO','WORLD'].forEach((word,line)=>[...word].forEach((ch,index)=>glyphs[ch].forEach((row,y)=>[...row].forEach((on,x)=>{if(on==='1')bricks.push({x:left+(index*6+x)*cell,y:top+(line*9+y)*cell,alive:true,revive:0});}))));paddle={x:w/2,y:h-35,width:clamp(w*.24,70,200),height:8};serve();lives=3;hud();draw();}
  function draw(){ctx.clearRect(0,0,w,h);const gap=cell*.2;for(const brick of bricks){ctx.fillStyle=brick.alive?'#f2efe9':'rgba(242,239,233,.06)';ctx.fillRect(brick.x+gap/2,brick.y+gap/2,cell-gap,cell-gap);}if(phase==='playing'||(phase==='attract'&&!reduce.matches)){ctx.fillStyle='#e8e4dc';ctx.fillRect(paddle.x-paddle.width/2,paddle.y,paddle.width,paddle.height);ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fill();}}
  function update(dt){clock+=dt;const demo=phase==='attract';if(demo){paddle.x=clamp(paddle.x+(ball.x-paddle.x)*Math.min(1,dt*7),paddle.width/2,w-paddle.width/2);bricks.forEach(b=>{if(!b.alive&&clock>b.revive)b.alive=true;});}ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;if(ball.x<ball.r){ball.x=ball.r;ball.vx=Math.abs(ball.vx);}if(ball.x>w-ball.r){ball.x=w-ball.r;ball.vx=-Math.abs(ball.vx);}if(ball.y<ball.r){ball.y=ball.r;ball.vy=Math.abs(ball.vy);}if(ball.vy>0&&ball.y+ball.r>=paddle.y&&ball.y-ball.r<=paddle.y+paddle.height&&Math.abs(ball.x-paddle.x)<paddle.width/2+ball.r){ball.y=paddle.y-ball.r;const angle=(ball.x-paddle.x)/(paddle.width/2)*1.1;const speed=Math.hypot(ball.vx,ball.vy);ball.vx=Math.sin(angle)*speed;ball.vy=-Math.cos(angle)*speed;}for(const b of bricks){if(b.alive&&ball.x+ball.r>b.x&&ball.x-ball.r<b.x+cell&&ball.y+ball.r>b.y&&ball.y-ball.r<b.y+cell){b.alive=false;b.revive=clock+1.5;ball.vy*=-1;break;}}if(ball.y>h+ball.r){if(demo)serve();else if(--lives<=0){phase='over';hud();}else{serve();hud();}}if(!demo&&bricks.every(b=>!b.alive)){phase='won';hud();}}
  function loop(now){raf=0;if(!visible||document.hidden)return;const dt=Math.min((now-last)/1000||0,.033);last=now;if(phase==='playing'||(phase==='attract'&&!reduce.matches)){for(let i=0;i<4;i++)update(dt/4);draw();startLoop();}else draw();}
  function startLoop(){if(!raf&&visible&&!document.hidden){if(!last)last=performance.now();raf=requestAnimationFrame(loop);}}
  function play(){phase='playing';reset();board.focus({preventScroll:true});startLoop();}
  button.addEventListener('click',e=>{e.stopPropagation();play();});
  board.addEventListener('pointermove',e=>{if(phase!=='playing')return;const r=board.getBoundingClientRect();paddle.x=clamp(e.clientX-r.left,paddle.width/2,w-paddle.width/2);});
  board.addEventListener('pointerdown',e=>{if(e.target===button)return;if(phase!=='playing')play();else{board.setPointerCapture(e.pointerId);paddle.x=clamp(e.clientX-board.getBoundingClientRect().left,paddle.width/2,w-paddle.width/2);}});
  board.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','Enter'].includes(e.key)){e.preventDefault();if(phase!=='playing')play();if(e.key==='ArrowLeft')paddle.x=clamp(paddle.x-cell*4,paddle.width/2,w-paddle.width/2);if(e.key==='ArrowRight')paddle.x=clamp(paddle.x+cell*4,paddle.width/2,w-paddle.width/2);draw();}});
  new ResizeObserver(()=>{reset();startLoop();}).observe(board);
  new IntersectionObserver(([e])=>{visible=e.isIntersecting;if(visible){last=0;startLoop();}else{cancelAnimationFrame(raf);raf=0;}}).observe(board);
  document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;}else{last=0;startLoop();}});
  reduce.addEventListener('change',()=>{draw();startLoop();});reset();
})();
